function me = ElementLHS4ConPen(nnpe,nqptv,wtq,bigN,bigNprime,detj,kmatrix,dampfac)% called by MechMet, MechMonics and QuadPoints2NodalPoints_FEpX%% forms elemental LHS  matrix for consistent penalty procedure for% determining nodal point values using quad point information%iend=nnpe;me = zeros(iend,iend);                                       for   k=1:1:nqptv       bigNqp = bigN(:,k)';    bigNprimeqp = bigNprime(:,:,k);                                      xkfac(k)=wtq(k)*detj(k);    me = me + xkfac(k)*(bigNqp' * bigNqp + dampfac * bigNprimeqp' * kmatrix' * kmatrix *  bigNprimeqp);      end